class Command(BaseCommand):
    help = "Carga la biblioteca completa en su etapa oculta dentro de la ruta enfocada."

    def add_arguments(self, parser):
        parser.add_argument(
            "--quitar", action="store_true", help="Borra la biblioteca entera."
        )

    @transaction.atomic
    def handle(self, *args, **opciones):
        if opciones["quitar"]:
            borrados, _ = Etapa.objects.filter(
                ruta=Etapa.Ruta.ENFOCADA, orden=ORDEN_BIBLIOTECA
            ).delete()
            self.stdout.write(
                self.style.WARNING(f"Biblioteca borrada ({borrados} registros).")
            )
            return

        etapa, _ = Etapa.objects.update_or_create(
            ruta=Etapa.Ruta.ENFOCADA,
            orden=ORDEN_BIBLIOTECA,
            defaults={
                "kicker": "Lectura",
                "titulo": "Biblioteca",
                "subtitulo": "Sin fecha y sin orden",
                "objetivo": "Los libros no se planifican: se leen cuando toca.",
                "color": "#c2703d",
                "oculta": True,
            },
        )

        nuevos = 0
        for i, fila in enumerate(LIBROS):
            titulo, fuente, detalle, etiqueta = fila[:4]
            en_ingles = fila[4] if len(fila) > 4 else False
            url = fila[5] if len(fila) > 5 else ""
            obj, creado = Item.objects.get_or_create(
                etapa=etapa,
                titulo=titulo,
                defaults={
                    "tipo": Item.Tipo.LIBRO,
                    "fuente": fuente,
                    "detalle": detalle,
                    "etiqueta": etiqueta,
                    "en_ingles": en_ingles,
                    "url": url or OL + quote_plus(titulo),
                    "orden": i,
                },
            )
            nuevos += creado
            if not creado and not obj.url:
                obj.url = url or OL + quote_plus(titulo)
                obj.save(update_fields=["url"])

        self.stdout.write(
            self.style.SUCCESS(
                f"Biblioteca lista: {etapa.items.count()} libros ({nuevos} nuevos)."
            )
        )
